public class ItemList {
    private final Item[] list;
    private int numOfItem;
    public static final int MAX = 100;

    public ItemList() {
        this.list = new Item[MAX];
        this.numOfItem = 0;
    }

    public boolean addItem(Item item) {
        if (item == null || numOfItem >= MAX) return false;
        list[numOfItem++] = item;
        return true;
    }

    public int findItemIndex(String creator) {
        if (creator == null) return -1;
        for (int i = 0; i < numOfItem; i++) {
            if (list[i].getCreator().equalsIgnoreCase(creator.trim())) return i;
        }
        return -1;
    }

    public boolean removeItem(int index) {
        if (index < 0 || index >= numOfItem) return false;
        for (int i = index; i < numOfItem - 1; i++) {
            list[i] = list[i + 1];
        }
        list[--numOfItem] = null;
        return true;
    }

    public void sortByValueAsc() {
        for (int i = 0; i < numOfItem - 1; i++) {
            for (int j = i + 1; j < numOfItem; j++) {
                if (list[i].getValue() > list[j].getValue()) {
                    Item tmp = list[i]; list[i] = list[j]; list[j] = tmp;
                }
            }
        }
    }
}

