import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    public static Map<String, Integer> countWords(String text) {
        if (text == null || text.isBlank()) return Collections.emptyMap();
        Map<String, Integer> freq = new HashMap<>();
        for (String token : text.trim().toLowerCase().split("\\s+")) {
            freq.put(token, freq.getOrDefault(token, 0) + 1);
        }
        return freq;
    }

    public static List<Product> loadProducts(String filePath) {
        List<Product> list = new ArrayList<>();
        File f = new File(filePath);
        if (!f.exists()) return list;

        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(new FileInputStream(f), StandardCharsets.UTF_8))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (line.isBlank()) continue;
                String[] parts = line.split(",");
                if (parts.length < 3) continue;
                try {
                    list.add(new Product(parts[0].trim(), parts[1].trim(), Double.parseDouble(parts[2].trim())));
                } catch (NumberFormatException ignored) {}
            }
        } catch (IOException e) {
            System.err.println("Read error: " + e.getMessage());
        }
        list.sort(Comparator.comparingDouble(Product::getPrice).reversed().thenComparing(Product::getId));
        return list;
    }
}
